print(f"\n计划新增字段数量: {len(new_fields)}")

# 生成新字段值的函数
def gen_field_value(liquor, field):
    abv = liquor.get('abv', 40)
    type_name = liquor.get('type', '')
    price = liquor.get('price', 100)
    score = liquor.get('score', 85)
    name = liquor.get('name', '')
    age = liquor.get('age', '')
    
    if field == 'oak_type':
        if '威士忌' in type_name or 'Whisky' in str(liquor.get('ename', '')):
            return random.choice(['美国橡木', '欧洲橡木', '西班牙雪莉桶', '法国橡木'])
        elif '白兰地' in type_name:
            return '法国特细橡木'
        elif '朗姆' in type_name:
            return '美国波本桶'
        return random.choice(['美国橡木', '欧洲橡木', '陶坛'])
    
    elif field == 'cocktail_recipe':
        if '威士忌' in type_name or 'Whisky' in str(liquor.get('ename', '')):
            return json.dumps({"name": "古典鸡尾酒", "ingredients": ["威士忌60ml", "方糖1块", "苦精2dash", "橙皮1片"], "method": "将方糖放入古典杯，加入苦精和少量水，搅拌至糖溶解。加入威士忌和冰块，橙皮装饰。"}, ensure_ascii=False)
        elif '金酒' in type_name or 'Gin' in str(liquor.get('ename', '')):
            return json.dumps({"name": "金汤力", "ingredients": ["金酒45ml", "汤力水150ml", "青柠角1个", "冰块适量"], "method": "在高球杯中放入冰块，倒入金酒，补满汤力水，青柠角装饰。"}, ensure_ascii=False)
        elif '伏特加' in type_name or 'Vodka' in str(liquor.get('ename', '')):
            return json.dumps({"name": "莫斯科骡子", "ingredients": ["伏特加45ml", "姜啤酒150ml", "青柠汁15ml", "冰块适量"], "method": "在铜杯中放入冰块，倒入伏特加和青柠汁，补满姜啤酒。"}, ensure_ascii=False)
        elif '朗姆' in type_name:
            return json.dumps({"name": "莫吉托", "ingredients": ["白朗姆45ml", "青柠汁30ml", "薄荷叶6-8片", "糖浆20ml", "苏打水适量"], "method": "将薄荷叶捣碎放入高球杯，加入朗姆、青柠汁和糖浆，搅拌均匀。补满苏打水，放上薄荷叶装饰。"}, ensure_ascii=False)
        elif '龙舌兰' in type_name:
            return json.dumps({"name": "玛格丽特", "ingredients": ["龙舌兰45ml", "君度30ml", "青柠汁30ml", "盐适量"], "method": "将龙舌兰、君度和青柠汁放入调酒壶，加冰摇匀。边缘沾盐的鸡尾酒杯滤冰倒入。"}, ensure_ascii=False)
        return json.dumps({"name": "嗨棒", "ingredients": ["烈酒45ml", "苏打水150ml", "冰块适量"], "method": "在高球杯中放入冰块，倒入烈酒，补满苏打水，搅拌均匀。"}, ensure_ascii=False)
    
    elif field == 'food_pairing':
        if '酱香型' in type_name:
            return json.dumps(["红烧肉", "烤鸭", "东坡肉", "叉烧", "卤味拼盘"], ensure_ascii=False)
        elif '浓香型' in type_name:
            return json.dumps(["宫保鸡丁", "回锅肉", "水煮鱼", "麻婆豆腐", "干锅系列"], ensure_ascii=False)
        elif '清香型' in type_name:
            return json.dumps(["清蒸鱼", "白切鸡", "凉拌菜", "海鲜", "蔬菜"], ensure_ascii=False)
        elif '威士忌' in type_name:
            return json.dumps(["牛排", "烤肉", "奶酪拼盘", "烟熏三文鱼", "坚果"], ensure_ascii=False)
        elif '白兰地' in type_name:
            return json.dumps(["鱼子酱", "松露", "鹅肝", "顶级牛排", "巧克力"], ensure_ascii=False)
        elif '伏特加' in type_name:
            return json.dumps(["鱼子酱", "腌鱼", "酸奶油", "黑面包", "蔬菜"], ensure_ascii=False)
        return json.dumps(["奶酪", "火腿", "坚果", "水果"], ensure_ascii=False)
    
    elif field == 'distillery_founded':
        founded_map = {
            '茅台': 1951, '泸州老窖': 1573, '五粮液': 1959, '汾酒': 1949, '洋河': 2003,
            '山崎': 1924, '余市': 1934, '麦卡伦': 1824, '格兰威特': 1886, '阿贝': 1815,
            '波摩': 1779, '云顶': 1828, '轩尼诗': 1765, '马爹利': 1715, '人头马': 1724,
            '绝对': 1879, '灰雁': 1997, '雪树': 1910, '亨利爵士': 1999, '添加利': 1830,
        }
        factory = liquor.get('factory', '')
        for k, v in founded_map.items():
            if k in factory:
                return v
        return random.randint(1850, 2010)
    
    elif field == 'finish':
        return random.choice(['短促', '中等', '中长', '悠长', '极悠长']) if abv < 50 else random.choice(['中长', '悠长', '极悠长'])
    
    elif field == 'complexity':
        return min(20, max(12, int(score / 5)))
    
    elif field == 'smoothness':
        return min(20, max(14, int(score / 4.5)))
    
    elif field == 'intensity':
        return min(20, max(13, int(score / 4.8)))
    
    elif field == 'balance':
        return random.randint(16, 20)
    
    elif field == 'value_score':
        return round(score / price * 80, 1) if price > 0 else 0
    
    elif field == 'availability':
        return '常见' if price < 500 else ('限量' if price < 2000 else '稀有')
    
    elif field == 'collection_value':
        if 'XO' in name or '25年' in age or '30年' in age or '50年' in age:
            return '极高'
        elif any(x in age for x in ['20年', '18年', '15年']):
            return '高'
        return '一般' if price < 500 else '中等'
    
    elif field == 'maturation':
        if '雪莉' in str(liquor.get('description', '')):
            return '西班牙雪莉桶熟化'
        elif '波本' in type_name:
            return '美国白橡木波本桶'
        elif '威士忌' in type_name:
            return random.choice(['首次填充橡木桶', '二次填充橡木桶', '混合橡木桶熟化'])
        return random.choice(['橡木桶陈酿', '不锈钢罐陈酿', '陶坛陈酿'])
    
    elif field == 'bottling_date':
        return random.choice(['2019', '2020', '2021', '2022', '2023', '2024', '2025'])
    
    elif field == 'alcohol_content':
        return f"{abv}%vol"
    
    elif field == 'distillation_style':
        if '单一麦芽' in type_name or 'Single Malt' in str(liquor.get('ename', '')):
            return '壶式蒸馏'
        elif '调和' in type_name:
            return '调和工艺'
        elif '伏特加' in type_name:
            return '连续蒸馏'
        elif '金酒' in type_name:
            return '再蒸工艺'
        return '传统蒸馏'
    
    elif field == 'aging_container':
        if '威士忌' in type_name:
            return random.choice(['美国白橡木桶', '欧洲橡木桶', '雪莉桶'])
        elif '白兰地' in type_name:
            return '法国特细橡木桶'
        return random.choice(['橡木桶', '陶坛', '不锈钢罐'])
    
    elif field == 'filtration':
        return '非冷凝过滤' if abv > 46 else random.choice(['冷凝过滤', '非冷凝过滤'])
    
    elif field == 'coloring':
        return '无' if '威士忌' not in type_name and '白兰地' not in type_name else random.choice(['无焦糖着色', '轻焦糖着色'])
    
    elif field == 'chill_filtered':
        return False if abv > 46 else random.choice([True, False])
    
    elif field == 'cask_strength':
        return '桶强' if abv >= 50 else ('原桶强度' if abv >= 46 else '标准装瓶强度')
    
    elif field == 'blending_detail':
        return '单一酒体' if '单一' in type_name else random.choice(['由多种年份酒体勾调', '由不同产区的酒体勾调', '由多种橡木桶酒体勾调'])
    
    elif field == 'quality_level':
        return '顶级' if score >= 95 else ('优秀' if score >= 90 else ('良好' if score >= 85 else '普通'))
    
    elif field == 'verification':
        return random.choice(['官方防伪标签', '二维码追溯系统', '封口防伪', '限量编号'])
    
    elif field == 'storage_years':
        if '年' in str(age):
            try:
                return int(''.join(filter(str.isdigit, str(age))))
            except:
                pass
        return random.randint(3, 30)
    
    return None

print("\n步骤1: 为现有350款酒添加新字段...")
for item in data:
    for field in new_fields:
        if field not in item:
            item[field] = gen_field_value(item, field)

